const main=$('#main');
const copyIcon='<span aria-hidden="true">▢</span>';
function navHTML(){return groups.map(([group,items])=>`<div class="nav-group"><div class="nav-label">${esc(group)}</div>${items.map(([title,path])=>`<a href="${path}" data-route class="nav-link ${currentPage?.path===path?'active':''}" ${currentPage?.path===path?'aria-current="page"':''}>${esc(title)}</a>`).join('')}</div>`).join('')+`<div class="nav-foot">Built for the web.<a href="/specification" data-route>전체 명세 읽기 ↗</a><a href="https://tossmini-docs.toss.im/tds-mobile/foundation/typography/" target="_blank" rel="noopener">Reference · Toss TDS ↗</a></div>`;}
function table(head,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${head.map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function section(id,title,body,description=''){return `<section class="section" id="${id}"><h2>${title}</h2>${description?`<p>${description}</p>`:''}${body}</section>`;}
function callout(title,text,neutral=false){return `<div class="callout ${neutral?'neutral':''}"><span class="callout-icon" aria-hidden="true">ⓘ</span><div><strong>${title}</strong><p>${text}</p></div></div>`;}
function rules(items){return `<div class="rules-grid">${items.map(([title,text],i)=>`<div class="rule-card"><div class="rule-no">0${i+1}</div><h3>${title}</h3><p>${text}</p></div>`).join('')}</div>`;}
function checklist(items){return `<ul class="checklist">${items.map(t=>`<li><span class="check" aria-hidden="true">✓</span><span>${t}</span></li>`).join('')}</ul>`;}
function codePanel(code,name='example.css'){return `<div class="code-panel"><div class="code-header"><span>${esc(name)}</span><button class="copy" data-copy-source>${copyIcon} 복사</button></div><pre><code>${esc(code)}</code></pre></div>`;}
function contract(p){return {id:p.title,version:'1.0.0',status:'stable',purpose:registry[p.title]?.purpose??desc[p.title]??p.title,useWhen:'화면의 목적과 필요한 상태가 이 계약에 부합할 때',avoidWhen:'기존 패턴으로 의미와 동작을 표현할 수 없을 때',props:registry[p.title]?.props.map(([name,type,defaultValue,description])=>({name,type,default:defaultValue,description}))??[],variants:registry[p.title]?.variants??[],stateAxes,statePrecedence:['disabled','loading','invalid/selected','interaction + focus-visible'],tokenBindings:{background:'bg.surface',text:'text.primary',primaryAction:'action.primary.bg'},keyboardBehavior:'Tab으로 접근, native 요소 또는 WAI-ARIA 패턴의 키보드 계약 준수',accessibility:['visible-focus','accessible-name','contrast-aa'],responsiveBehavior:'docs-default; 360px~1920px; 200% 글자·400% 브라우저 확대 검수',i18nBehavior:'외부 문자열 주입, 한영 혼합, 긴 텍스트 50% 확장',events:['change','activate'],examples:[p.path],acceptanceCriteria:['keyboard-complete','no-page-overflow','no-duplicate-action'],deprecatedReplacement:null};}
function preview(demo,code,spec=contract(currentPage),controls=''){return `<div class="preview"><div class="preview-toolbar"><div class="tabs" role="tablist" aria-label="예제 보기"><button class="tab" id="tab-preview" role="tab" aria-selected="true" aria-controls="panel-preview" data-tab="preview">Preview</button><button class="tab" id="tab-code" role="tab" aria-selected="false" tabindex="-1" aria-controls="panel-code" data-tab="code">Code</button><button class="tab" id="tab-spec" role="tab" aria-selected="false" tabindex="-1" aria-controls="panel-spec" data-tab="spec">Specification</button></div><div class="preview-controls">${controls}</div></div><div class="preview-content" id="panel-preview" role="tabpanel" aria-labelledby="tab-preview">${demo}</div><div id="panel-code" role="tabpanel" aria-labelledby="tab-code" hidden>${codePanel(code)}</div><div id="panel-spec" role="tabpanel" aria-labelledby="tab-spec" hidden>${codePanel(JSON.stringify(spec,null,2),'contract.json')}</div><div class="preview-foot"><span><code>Hudson Web / ${esc(currentPage.title)}</code> <span aria-hidden="true">·</span> 실제로 조작해 보세요</span><button class="copy" data-copy-contract>${copyIcon} 명세 복사</button></div></div>`;}
function header(p){return `<div class="breadcrumb"><a href="/overview" data-route>Design System</a><span aria-hidden="true">/</span><span>${esc(p.group)}</span><span aria-hidden="true">/</span><span>${esc(p.title)}</span></div><header class="page-head"><div class="page-title-row"><h1 id="pageTitle" tabindex="-1">${esc(p.title)}</h1><span class="stable-badge">Stable</span></div><p class="page-description">${esc(desc[p.title]??registry[p.title]?.purpose??pageDesc(p.title))}</p><div class="page-meta"><span>◷ 2026. 10. 10.</span><span>◇ Web foundation</span><span>접근성 · 반응형</span></div></header>`;}
function pageDesc(t){return ({Overview:'Hudson AI의 웹을 만드는 명확한 기준. 사람과 AI가 같은 언어로 설계하고, 일관된 결과를 만듭니다.','Getting Started':'목적을 정의하고, 토큰을 선택하고, 검증된 컴포넌트를 조합하세요. 웹에 필요한 기준부터 시작합니다.','Design Principles':'보기 좋은 화면을 넘어, 다음 행동이 명확한 화면을 만듭니다. UX 법칙을 실행 가능한 판단 기준으로 사용해요.','AI Kit':'AI가 새 규칙을 만들기 전에, 이미 정한 기준을 읽게 하세요. 명세·토큰·컴포넌트 계약을 함께 전달합니다.',Specification:'설계 이유부터 기술 계약과 검수 조건까지. 원본 명세의 모든 내용을 확인하고 내려받을 수 있어요.',Changelog:'시스템의 변경을 추적합니다. 호환되는 추가와 호환성이 바뀌는 변경을 구분해요.'})[t]??'Hudson의 실제 작업 맥락에 맞춘 웹 패턴입니다. 상태와 복구 행동까지 명확하게 정의합니다.';}
function typography(){
 const demo=`<div class="type-stage" id="typeStage"><div class="eyebrow" lang="en">GIVE YOUR WORDS A VOICE</div><div class="specimen-title" id="specimenTitle">모든 목소리에 의미를 더하다.</div><p class="specimen-body" id="specimenBody">언어가 달라져도, 전하고 싶은 마음은 그대로.<br>명확한 위계와 읽기 편한 리듬으로 경험을 설계합니다.</p><div class="specimen-caption"><span aria-hidden="true">↳</span><span>Heading LG · Body MD · Caption</span></div></div>`;
 const controls=`<label for="locale" class="sr-only">예제 언어</label><select id="locale" class="mini-select"><option value="ko">한국어</option><option value="en">English</option><option value="mixed">한영 혼합</option></select><button class="copy" id="narrowToggle" aria-pressed="false" aria-label="좁은 화면 미리보기">▯</button><label for="typeScale" class="sr-only">예제 글자 확대</label><select id="typeScale" class="mini-select"><option value="1">100%</option><option value="2">200%</option></select>`;
 const css='.heading-lg {\n  font-size: var(--hds-font-heading-lg);\n  line-height: 1.25;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n}\n\n.body-md {\n  font-size: var(--hds-font-body-md);\n  line-height: 1.6;\n}';
 return section('preview','직접 확인하기',preview(demo,css,{...contract(currentPage),tokens:typeTokens.map(([name,size,lineHeight,weight,usage])=>({name,size,lineHeight,weight,usage}))},controls),'언어, 화면 폭, 글자 크기를 바꾸며 타이포그래피의 역할을 확인하세요.')+
 section('tokens','Typography tokens',table(['Token / CSS variable','Size / Line','Weight','Usage'],typeTokens.map(([name,size,line,weight,use])=>[`<span class="token-name">${name}</span><code>--hds-font-${name}</code>`,`<span class="token-numeric">${size}<br>${line}</span>`,weight,`<span class="type-example ${name.startsWith('heading')?'big':''}">${use}</span>`]),'type-table'),'숫자를 외우는 대신 역할을 선택하세요. 토큰의 기본 값은 루트 글꼴 16px을 기준으로 합니다.')+
 callout('값 대신 토큰을 사용하세요.','폰트 크기를 화면마다 하드코딩하면 확대와 일관성에 대응하기 어려워요. <code>rem</code>과 역할 토큰을 사용하고, 브라우저의 기본 글꼴 설정을 존중합니다.')+
 section('rules','사용 규칙',rules([['역할을 먼저 선택하기','크기가 비슷해도 역할이 다르면 토큰이 다릅니다. 제목, 본문, 라벨을 의미에 맞게 선택하세요.'],['의미와 스타일 분리하기','heading-md를 사용하더라도 문서 구조에 따라 H2일 수 있어요. HTML의 의미를 크기로 결정하지 않습니다.'],['읽어야 할 정보는 읽기 쉽게','설명과 오류를 작은 글자로 밀어내지 않습니다. 긴 텍스트가 잘리지 않도록 높이는 유연하게 둡니다.'],['한글과 영문을 함께 고려하기','keep-all과 overflow-wrap으로 문장과 URL을 처리하고, 50% 길어진 번역에서도 레이아웃을 확인합니다.']]))+
 section('accessibility','접근성과 반응형',checklist(['브라우저 기본 글꼴을 유지하고 html font-size는 100%로 설정합니다.','200% 글자 확대와 400% 브라우저 확대에서도 텍스트와 행동이 잘리지 않아야 합니다.','텍스트와 배경의 대비를 확인합니다. 작은 글자는 최소 4.5:1을 기준으로 합니다.','문서 H1은 하나만 사용하고 제목의 논리적 순서를 유지합니다.','모바일은 heading-xl 2rem, heading-lg 1.75rem을 사용하며 정보 우선순위는 유지합니다.']))+
 section('implementation','구현하기',codePanel(css))+
 section('ai-contract','AI 구현 계약',contractBox())+
 section('related','관련 문서',related(['/foundations/color','/foundations/layout','/guidelines/accessibility']));
}
function contractBox(){return `<div class="section-title-row"><p>기존 토큰과 컴포넌트에서 선택하고, 상태와 검수 조건을 함께 전달하세요.</p><button class="copy" data-download-contract>JSON 다운로드 ↓</button></div>${codePanel(JSON.stringify(contract(currentPage),null,2),'component-contract.json')}`;}
function related(paths){return `<div class="rules-grid">${paths.map(path=>{const p=pages.find(x=>x.path===path);return `<a class="rule-card" href="${path}" data-route><h3>${esc(p.title)} ↗</h3><p>${esc(desc[p.title]??'적용 기준과 동작 계약을 확인하세요.')}</p></a>`;}).join('')}</div>`;}
function foundation(p){let demo,rows,heads,code,notes;
 if(p.title==='Color'){
 demo=`<div class="swatch-grid">${colors.map(([name,value])=>`<button class="swatch" data-copy="${value}" aria-label="${name} ${value} 복사"><div class="swatch-color" style="background:var(--${name})"></div><div class="swatch-info"><strong>${name}</strong><span>${value}</span></div></button>`).join('')}</div>`;
 heads=['Semantic token','Primitive','Role'];rows=[['bg.canvas','warm-50','전체 배경'],['bg.surface','warm-0','콘텐츠 표면'],['text.primary','warm-950','핵심 텍스트'],['text.secondary','warm-600','설명 텍스트'],['text.brand','orange-700','작은 강조 텍스트'],['action.primary.bg','orange-500','주요 행동 배경'],['action.primary.fg','warm-950','주요 행동 글자'],['border.control','warm-500','입력 경계']];
 code=':root {\n  --hds-action-primary-bg: #fd4d20;\n  --hds-action-primary-fg: #171614;\n  --hds-text-brand: #c73512;\n}\n.button-primary {\n  background: var(--hds-action-primary-bg);\n  color: var(--hds-action-primary-fg);\n}';
 notes=callout('밝은 오렌지 위에는 차콜 글자를 사용합니다.','#FD4D20 / #FFFFFF는 3.355:1, 차콜 #171614와는 5.390:1입니다. 작은 흰 글자가 필요하면 배경을 #C73512로 바꾸세요. 상태는 텍스트와 아이콘도 함께 표시합니다.');
 }else if(p.title==='Spacing'){
 const vals=[4,8,12,16,24,32,48,64,96];demo=`<div class="scale-row">${vals.map(v=>`<div class="scale-item"><div class="scale-block" style="height:${v/16}rem;width:${v/16}rem"></div><div class="scale-label">${v}px</div></div>`).join('')}</div>`;heads=['Token','Value','Use'];rows=vals.map(v=>[`space.${v}`,`${v}px`,v<=16?'요소 내부':v<=32?'그룹 간':'섹션 간']);code='.field { gap: var(--hds-space-8); }\n.card { padding: var(--hds-space-24); }\n.section { margin-block-start: var(--hds-space-48); }';notes=callout('가까우면 같은 그룹, 멀면 다른 그룹','그룹 안은 8–16px, 그룹 사이는 24–32px을 시작 기준으로 사용합니다. 선 두께·폰트·아이콘 크기는 spacing scale과 별도입니다.');
 }else if(p.title==='Radius'){
 const vals=[0,4,8,12,16,999];demo=`<div class="scale-row">${vals.map(v=>`<div class="scale-item"><div class="radius-block" style="border-radius:${v===999?'50%':v/16+'rem'}"></div><div class="scale-label">${v===999?'Full':v+'px'}</div></div>`).join('')}</div>`;heads=['Token','Value','Use'];rows=[['radius.none','0','직선 구조'],['radius.code','4px','코드'],['radius.control','8px','버튼·입력'],['radius.card','12px','카드'],['radius.modal','16px','Dialog'],['radius.full','9999px','아바타·상태점']];code='.button { border-radius: var(--hds-radius-control); }\n.card { border-radius: var(--hds-radius-card); }';notes=callout('역할에 맞는 곡률을 선택하세요.','화면마다 10px, 14px처럼 임의 값을 추가하지 않습니다. 같은 역할은 같은 radius로 반복합니다.');
 }else if(p.title==='Elevation'){
 demo=`<div class="scale-row">${['none','var(--shadow-sm)','var(--shadow-md)','var(--shadow-lg)'].map((v,i)=>`<div><div class="shadow-block" style="box-shadow:${v}"></div><div class="scale-label">Elevation ${i}</div></div>`).join('')}</div>`;heads=['Token','Shadow','Use'];rows=[['elevation-0','none','일반 카드·패널'],['elevation-1','0 2px 8px / 8%','작은 부유 요소'],['elevation-2','0 8px 24px / 12%','메뉴·팝오버'],['elevation-3','0 16px 48px / 18%','모달']];code='.popover { box-shadow: var(--hds-elevation-2); }\n.dialog { box-shadow: var(--hds-elevation-3); }';notes=callout('모든 카드에 그림자를 붙이지 않습니다.','배경, 선, 간격으로 위계를 만들고 깊이는 실제 떠 있는 요소에 사용합니다. z-index도 정해진 레이어를 선택하세요.');
 }else if(p.title==='Layout'){
 demo='<div class="mini-layout"><div>Navigation<br>240px</div><div>Main content<br>minmax(0, 1fr)</div><div>On this page<br>192px</div></div>';heads=['Viewport','Navigation','Main / TOC'];rows=[['≥1280px','240px 고정','3열 · 오른쪽 목차'],['1024–1279px','224px 고정','2열 · 본문 목차'],['768–1023px','Drawer','24px 패딩'],['<768px','Drawer','16px 패딩']];code='.docs-shell {\n  display: grid;\n  grid-template-columns: 15rem minmax(0, 1fr) 12rem;\n  gap: 2rem;\n  max-width: 90rem;\n}\n.docs-main { min-width: 0; }';notes=callout('모바일 앱의 구조를 그대로 확장하지 않습니다.','웹의 넓은 작업 영역, 키보드, 표와 코드의 독립 스크롤을 지원합니다. 좁은 화면에서 정보와 작업을 삭제하지 않습니다.');
 }else if(p.title==='Motion'){
 demo='<div class="demo-stack"><p>상태 변화는 짧고 명료하게.</p><div class="button-row"><button class="button primary" id="motionDemo">상태 전환 보기</button><span id="motionStatus" class="badge">대기</span></div><p class="field-help">기기의 reduced-motion 설정을 따릅니다.</p></div>';heads=['Token','Duration','Use'];rows=[['instant','0ms','즉시 변화'],['fast','120ms','hover·색'],['standard','180ms','상태 전환'],['slow','240ms','레이어 전환']];code='transition: opacity 180ms cubic-bezier(.2,0,0,1);\n@media (prefers-reduced-motion: reduce) {\n  .motion-element { transition: none; animation: none; }\n}';notes=callout('움직임을 줄여도 정보는 유지합니다.','진행 상태나 완료 안내까지 숨기지 않습니다. 큰 이동·확대·반복은 reduced-motion에서 제거합니다.');
 }else{
 demo='<div class="button-row"><button class="icon-button" aria-label="검색" data-open-search>⌕</button><button class="icon-button" aria-label="문서 명세 다운로드" data-download-contract>↓</button><button class="icon-button" aria-label="복사" data-copy-contract>▢</button><button class="icon-button" aria-label="설정 예제 열기" data-open-dialog>⚙</button></div>';heads=['Size','Use','Target'];rows=[['16px','조밀한 메타','실제 target 별도'],['20px','일반 UI','40px 이상'],['24px','주요 컨트롤','44px 이상']];code='<button aria-label="검색 열기">\n  <svg aria-hidden="true">...</svg>\n</button>';notes=callout('아이콘 크기와 클릭 영역은 다릅니다.','icon-only에는 접근 가능한 이름을 제공하고 주요 조작은 44px 클릭 영역을 권장합니다. hover에만 필수 정보를 넣지 않습니다.');
 }
 return section('preview','직접 확인하기',preview(demo,code))+section('tokens','Tokens & roles',table(heads,rows))+notes+section('rules','사용 규칙',rules([['역할에서 선택하기','원시 값을 화면에 직접 입력하지 않고 semantic token을 사용하세요.'],['예외를 기록하기','새 값이 필요하면 이유·범위·검토일을 남기고 시스템에 반영하세요.']]))+section('implementation','구현하기',codePanel(code))+section('ai-contract','AI 구현 계약',contractBox())+section('full-spec','상세 명세',specExcerpt(p.title));
}
function demoFor(t){
 switch(t){
 case 'Button':return `<div class="demo-stack"><div><div class="demo-label">Variants</div><div class="button-row"><button class="button primary" data-demo-action>프로젝트 생성</button><button class="button secondary" data-demo-action>가져오기</button><button class="button ghost" data-demo-action>미리보기</button><button class="button danger" data-open-dialog>삭제</button></div></div><div><div class="demo-label">States</div><div class="button-row"><button class="button primary" id="loadingDemo">로딩 상태 보기</button><button class="button secondary" disabled>사용 불가</button><span class="field-help">비활성 이유: 편집 권한이 필요해요.</span></div></div><div><div class="demo-label">Sizes</div><div class="button-row"><button class="button secondary sm" data-demo-action>보조 작업</button><button class="button secondary" data-demo-action>일반 작업</button><button class="button secondary lg" data-demo-action>주요 작업</button></div></div></div>`;
 case 'Link':return '<div class="demo-stack"><a class="text-link" href="/foundations/typography" data-route>Typography 문서로 이동 →</a><a class="text-link" href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener">WCAG 대비 기준 ↗</a></div>';
 case 'Field':case 'TextInput':return '<form id="inputDemo" class="demo-stack"><div class="field"><label for="projectName">프로젝트 이름 <span aria-hidden="true">*</span></label><input class="input" id="projectName" name="projectName" aria-describedby="nameHelp nameError" placeholder="예: Hudson 브랜드 필름" required><span class="field-help" id="nameHelp">2자 이상 입력하세요. 제출하거나 입력을 마치면 검증합니다.</span><span class="field-error" id="nameError" hidden></span></div><div class="button-row"><button class="button primary" type="submit">프로젝트 생성</button><button class="button ghost" type="reset">초기화</button></div></form>';
 case 'Select':return '<div class="field"><label for="languageSelect">번역 언어</label><select class="input" id="languageSelect"><option>한국어</option><option>English</option><option>日本語</option><option>Español</option></select><span class="field-help" id="selectStatus" role="status">한국어가 선택되었습니다.</span></div>';
 case 'Combobox':return '<div class="field"><label for="languageCombo">번역 언어 검색</label><input class="input" id="languageCombo" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="languageOptions" autocomplete="off" placeholder="언어를 입력하세요"><div id="languageOptions" role="listbox" hidden></div><span class="field-help" id="comboStatus" role="status">Arrow 키로 이동하고 Enter로 선택하세요.</span></div>';
 case 'Checkbox':return '<div class="demo-stack"><label><input type="checkbox" checked> 원본 배경음 유지</label><label><input type="checkbox"> 자막 파일 함께 내보내기</label><label><input type="checkbox" disabled> 검토자에게 자동 알림 — 관리자 설정 필요</label></div>';
 case 'Radio':return '<fieldset style="border:0;padding:0;margin:0"><legend class="demo-label">출력 품질</legend><div class="demo-stack"><label><input type="radio" name="quality" value="standard" checked> 표준 품질</label><label><input type="radio" name="quality" value="high"> 고품질</label></div></fieldset>';
 case 'Switch':return '<div class="button-row"><button class="button secondary" role="switch" aria-checked="false" id="switchDemo">자동 저장 · 꺼짐</button><span id="switchStatus" class="field-help" role="status">설정은 예제에만 적용됩니다.</span></div>';
 case 'Tabs':return '<p>상단 Preview / Code / Specification 탭이 이 컴포넌트의 작동 예제입니다. 방향키로 탭을 이동하고 각 패널을 확인하세요.</p>';
 case 'Badge':return '<div class="button-row"><span class="badge">대기</span><span class="badge success">✓ 완료</span><span class="badge warning">! 검토 필요</span><span class="badge danger">× 실패</span></div>';
 case 'Alert':return callout('파일을 처리하지 못했어요.','입력한 정보는 유지됩니다. 다시 시도하거나 파일 형식을 확인하세요.',true)+'<div class="button-row" style="margin-top:var(--s4)"><button class="button secondary" data-retry>다시 시도</button></div>';
 case 'Toast':return '<button class="button primary" id="toastDemo">완료 알림 보기</button>';
 case 'Tooltip':return '<div class="field"><button class="button secondary" id="tooltipTrigger" aria-describedby="tooltipText">보조 설명 확인</button><span class="field-help" role="tooltip" id="tooltipText" hidden>중요한 정보는 Tooltip에만 넣지 않습니다.</span><p class="field-help">마우스를 올리거나 키보드로 초점을 이동하세요.</p></div>';
 case 'Dialog':return '<button class="button primary" data-open-dialog>확인 Dialog 열기</button>';
 case 'Drawer':return '<button class="button primary" id="drawerDemo">문서 탐색 Drawer 열기</button>';
 case 'Table':return tableDemo();
 case 'Pagination':return '<nav class="button-row" aria-label="예제 페이지 이동"><button class="button secondary" id="prevPage" disabled>이전</button><span id="pageIndicator" aria-live="polite">1 / 3</span><button class="button secondary" id="nextPage">다음</button></nav><p class="field-help" style="margin-top:var(--s4)">데모 페이지 범위를 변경합니다.</p>';
 case 'Skeleton':return '<div id="skeletonArea" aria-busy="true" aria-label="콘텐츠 로딩 중"><div class="skeleton"></div><div class="skeleton" style="max-width:80%"></div><div class="skeleton" style="max-width:60%"></div></div><button class="button secondary" id="skeletonLoad" style="margin-top:var(--s4)">데모 로딩 완료</button>';
 case 'Progress':return '<div class="field"><label for="progressRange">데모 완료율</label><input id="progressRange" type="range" min="0" max="100" value="40"><progress id="demoProgress" value="40" max="100" aria-label="데모 완료율"></progress><span id="progressLabel" class="field-help" role="status">40% · 데모 데이터</span></div>';
 }
}
function component(p){const c=registry[p.title],code=componentCode(p.title);return section('preview','직접 확인하기',preview(demoFor(p.title),code))+
 section('rules','언제 사용하나요?',rules([[p.title==='Link'?'다른 위치로 이동할 때':'목적이 명확할 때',c.purpose],['피해야 할 사용','같은 맥락에 경쟁하는 주요 행동을 반복하거나, 기능을 hover에만 노출하지 않습니다.']]))+
 section('states','States',table(['State','Behavior'],c.states.map(s=>[`<code>${s}</code>`,stateDescription(s)])),'상태는 모양과 동작을 함께 정의합니다. focus-visible은 오류·선택 상태와 함께 유지합니다.')+
 section('api','API',table(['Prop','Type','Default','Description'],c.props.map(r=>r.map((v,i)=>i<2?`<code>${esc(v)}</code>`:esc(v)))))+
 section('accessibility','접근성과 반응형',checklist(['보이는 라벨 또는 접근 가능한 이름이 있어야 합니다.','Tab과 native 요소 또는 WAI-ARIA 패턴의 키보드 동작을 지원합니다.','Dialog는 초점을 내부에 유지하고 닫을 때 호출 위치로 복귀합니다.','일반 조작은 최소 40px, 터치·주요 조작은 44px 영역을 권장합니다.','긴 라벨과 200% 확대에서 정보·행동이 잘리지 않아야 합니다.']))+
 section('implementation','구현하기',codePanel(code,p.title.toLowerCase()+'.html'))+section('ai-contract','AI 구현 계약',contractBox());}
function componentCode(t){if(t==='Button')return '<button type="button" class="button primary">\n  프로젝트 생성\n</button>\n<!-- type 기본값은 button. submit은 명시적으로 선택합니다. -->';if(['TextInput','Field'].includes(t))return '<label for="project-name">프로젝트 이름</label>\n<input id="project-name" aria-describedby="help error" />\n<p id="help">2자 이상 입력하세요.</p>\n<p id="error" hidden></p>';return `<!-- ${t}: 원본 계약의 props·상태·접근성 기준을 적용합니다. -->\n${demoFor(t)}`;}
function stateDescription(s){return ({hover:'포인터 반응을 제공하지만 필수 정보를 숨기지 않습니다.',pressed:'실행 중인 클릭의 시각 반응입니다.','focus-visible':'키보드 초점을 2px outline으로 표시합니다.',disabled:'실행을 차단하고 이유를 인접 설명으로 제공합니다.',loading:'실제 비동기 처리 중입니다. 중복 실행을 차단하고 라벨을 유지합니다.',invalid:'오류 문구와 aria-invalid를 함께 제공합니다.',error:'실패 원인과 복구 경로를 표시하고 입력을 보존합니다.',indeterminate:'확정되지 않은 완료율을 숫자로 꾸미지 않습니다.',selected:'텍스트·속성·시각 상태를 함께 제공합니다.'})[s]??'의미와 시각 상태를 일치시키고 키보드·스크린리더에서도 확인 가능하게 합니다.';}
function tableDemo(){return '<div class="demo-stack"><div class="field"><label for="tableFilter">프로젝트 검색</label><input class="input" id="tableFilter" type="search" placeholder="프로젝트 이름"></div><div class="table-wrap"><table><caption class="sr-only">데모 프로젝트 목록</caption><thead><tr><th scope="col"><input type="checkbox" id="selectAll" aria-label="표시된 프로젝트 모두 선택"></th><th scope="col" id="sortHeader" aria-sort="none"><button class="button ghost sm" id="sortTable">프로젝트 ↕</button></th><th scope="col">언어</th><th scope="col">상태</th></tr></thead><tbody id="demoRows"></tbody></table></div><span id="tableStatus" class="field-help" role="status">데모 데이터 · 3개 프로젝트</span></div>';}
function pattern(p){let demo,code,r;
 if(p.title==='Upload'){demo='<div class="dropzone" id="dropzone"><h3>파일을 여기에 놓아주세요.</h3><p>또는 직접 파일을 선택하세요.<br>데모에서는 이름·크기만 확인하며 서버로 전송하지 않습니다.</p><label for="fileInput" class="button primary" tabindex="0" id="fileLabel">파일 선택</label><input class="sr-only" id="fileInput" type="file" multiple><div id="fileResults" class="field-help" aria-live="polite" style="margin-top:var(--s4)"></div></div>';code='<input type="file" multiple />\n<!-- 서버 형식·크기 검증 필수. 데모는 서버 업로드하지 않습니다. -->';r=[['드래그와 버튼을 함께','드래그 없이 키보드로도 같은 작업을 수행할 수 있어야 합니다.'],['실제 제한을 표시','지원 형식·최대 크기는 제품 설정에서 가져오고 서버에서도 검증합니다.']];}
 else if(p.title==='AsyncJob'){demo='<div class="demo-stack"><span class="badge">데모 데이터</span><div><div class="job-status"><strong id="jobStage">작업 대기</strong><span id="jobState" role="status">queued</span></div><progress id="jobProgress" max="100" value="0" aria-label="작업 진행"></progress></div><div class="button-row"><button class="button primary" id="jobStart">데모 작업 실행</button><button class="button secondary" id="jobCancel" disabled>작업 취소</button><button class="button ghost" id="jobFail">실패 상태 보기</button></div><p class="field-help">실제 처리 서비스가 아닌 상태 전이 예제입니다. 완료율 미확정 상태는 indeterminate로 표시합니다.</p></div>';code='queued → running → succeeded\n                  → failed\n         → canceling → canceled\n\n// 서버 percent가 없으면 value 없는 progress를 사용합니다.';r=[['진행 단계와 완료율 구분','API가 완료율을 주지 않으면 단계만 표시합니다. 임의로 99%까지 증가시키지 않습니다.'],['복구와 중복 방지','실패 후 재시도 조건, idempotency와 중복 과금 정책을 실제 제품에 맞게 정의합니다.']];}
 else if(p.title==='MediaWorkspace'){demo=`<span class="badge">인터랙션 데모 · 실제 음원 없음</span><div class="inverse" style="margin-top:var(--s4)"><div class="media-toolbar"><span>HUDSON / VOICE WORKSPACE</span><span>00:24</span></div><div class="waveform" aria-hidden="true">${Array.from({length:60},(_,i)=>`<span style="--bar-height:${12+((i*37)%70)}%"></span>`).join('')}</div><div class="media-controls"><button class="button primary" id="mediaPlay" aria-label="타임라인 데모 재생">▶ 재생</button><label class="sr-only" for="mediaSeek">타임라인 위치</label><input type="range" id="mediaSeek" min="0" max="24" value="0"><span id="mediaTime">00:00</span></div></div><div class="transcript"><small>화자 01 · English → 한국어</small>언어가 달라져도, 전하고 싶은 마음은 그대로.</div>`;code='MediaWorkspace = Preview + Timeline + Transcript + Inspector\n// 파형에는 DOM 기반 재생·탐색 컨트롤을 함께 제공합니다.';r=[['미디어와 검수 영역 분리','차콜은 Preview에 사용하고 텍스트를 읽는 영역은 가독성을 우선합니다.'],['시각에만 의존하지 않기','화자는 이름·번호를 함께 표시하고 파형에는 접근 가능한 재생·탐색 컨트롤을 제공합니다.']];}
 else if(p.title==='LiveSession'){demo='<div class="demo-stack"><div class="button-row"><span class="badge success" id="liveBadge">● 연결됨</span><span class="field-help">데모 세션</span></div><div class="field"><label for="liveLanguage">송출 언어</label><select class="input" id="liveLanguage"><option>한국어</option><option>English</option><option>日本語</option></select></div><div class="button-row"><button class="button secondary" id="liveDisconnect">연결 끊김 시연</button><button class="button primary" id="liveReconnect" hidden>다시 연결</button></div><span class="field-help" id="liveStatus" role="status">실제 송출이나 네트워크에 연결되지 않은 데모입니다.</span></div>';code='connected → disconnected → reconnecting → connected | failed\n// 상태·갱신 시각·영향·복구 행동을 함께 표시합니다.';r=[['연결 상태를 정확히','실시간이라는 문구 대신 연결됨·끊김·재연결·실패를 구분합니다.'],['사용자 영향 표시','마지막 갱신 시각과 복구 행동을 함께 제공하고 색상점만으로 알리지 않습니다.']];}
 else if(p.title==='EmptyState'){demo='<div class="empty-state"><div class="demo-label">PROJECTS</div><h3>아직 프로젝트가 없어요.</h3><p>첫 파일을 가져와 작업을 시작하세요.</p><a class="button primary" href="/patterns/upload" data-route>파일 가져오기</a></div>';code='empty ≠ filtered-empty ≠ permission-denied ≠ network-error';r=[['상태를 구별하기','데이터 없음, 검색 결과 없음, 권한 부족을 같은 화면으로 처리하지 않습니다.'],['다음 행동 제공','해당 상태를 벗어날 수 있는 명확한 행동을 제시합니다.']];}
 else if(p.title==='ErrorRecovery'){demo=callout('연결을 확인해 주세요.','데모 오류 상태입니다. 입력한 정보는 유지되고, 다시 시도할 수 있어요.',true)+'<div class="button-row" style="margin-top:var(--s4)"><button class="button primary" data-retry>다시 시도</button></div>';code='error → retrying → restored | error\n// 사용자 입력과 선택을 보존합니다.';r=[['확인된 원인만 안내','알 수 없는 실패 원인을 추측해 단정하지 않습니다.'],['작업을 보존하기','재시도할 때 입력과 선택을 유지하고 중요한 실패는 본문에 남깁니다.']];}
 else {demo='<div class="mini-layout"><div>Navigation</div><div>Workspace<br>목적과 다음 행동</div><div>Inspector / TOC</div></div>';code=p.title==='DocsShell'?'Header 64px + Navigation 240px + Main + TOC 192px':'Header 64px + Navigation 240px + Main + Inspector 320px';r=[['화면 폭에 맞춰 재배치','좁은 화면에서는 보조 영역을 접근 가능한 Drawer로 이동합니다.'],['기본 맥락 유지','sticky·내부 스크롤이 초점을 가리지 않는지 확인합니다.']];}
 return section('preview','작동 예제',preview(demo,code))+section('rules','패턴 규칙',rules(r))+section('states','상태와 복구',checklist(['실제 데이터와 데모 데이터를 명확히 구분합니다.','실패·취소·재시도를 함께 설계하고 중복 작업을 차단합니다.','hover나 드래그만으로 작업할 수 있게 만들지 않습니다.','키보드와 좁은 화면에서도 핵심 작업을 유지합니다.']))+section('implementation','구현 계약',codePanel(code,'pattern.contract'))+section('ai-contract','AI 구현 계약',contractBox())+section('full-spec','상세 명세',specExcerpt(p.title));
}
function overview(){return section('start','하나의 기준, 일관된 경험',`<div class="full-grid"><a class="overview-card" href="/foundations/typography" data-route><span class="rule-no">01 / FOUNDATIONS</span><h3>역할을 정하다.</h3><p>색·타이포·여백의 기준을 선택하세요.</p></a><a class="overview-card" href="/components/button" data-route><span class="rule-no">02 / COMPONENTS</span><h3>기준을 조합하다.</h3><p>모양, 상태, 접근성이 정의된 UI.</p></a><a class="overview-card" href="/ai-kit" data-route><span class="rule-no">03 / AI KIT</span><h3>실행을 위임하다.</h3><p>사람과 AI가 읽는 같은 계약.</p></a></div>`)+section('philosophy','정확하고, 명료하고, 빠르게',rules([['Brand, in context','화이트·웜그레이로 구조를 만들고 오렌지는 다음 행동을 강조합니다.'],['Built for the web','키보드, 넓은 화면, 데이터 표, 브라우저 확대를 기본으로 고려합니다.'],['Choose, don’t invent','AI는 새로운 값을 만들기보다 정의된 토큰과 컴포넌트를 선택합니다.'],['Complete means usable','검색, 이동, 상태, 실패 복구가 실제로 작동해야 완성입니다.']]))+section('reference','레퍼런스와 범위',callout('Toss TDS의 문서 구조를 참고했습니다.','좌측 탐색·중앙 설명과 예제·우측 목차를 Hudson의 웹 환경에 맞게 구성했습니다. 토스의 브랜드·자산·전용 패키지를 사용하지 않습니다.',true))+section('related','시작하기',related(['/getting-started','/principles','/specification']));}
function aiKit(){const brief={schemaVersion:'1.0.0',systemVersion:'1.0.0',screenId:'docs.typography',purpose:'역할별 타이포 토큰을 선택하고 적용한다',audience:['designer','developer','ai'],primaryAction:{label:'명세 복사',actionId:'copy-spec'},secondaryActions:['copy-code','change-preview-locale'],layout:'DocsShell',density:'comfortable',theme:'light',contentPriority:['purpose','preview','tokens','rules','api'],requiredStates:['ready','search-empty','copy-success','copy-error'],dataSource:'static-registry',responsivePolicy:'docs-default',acceptanceCriteria:['keyboard-complete','no-page-overflow','contrast-aa']};return section('download','AI에 전달할 자료',`<div class="button-row"><a class="button primary" href="/assets/Hudson_AI_Web_Design_System_Spec.md" download>전체 명세 다운로드 ↓</a><a class="button secondary" href="/tokens.json" download>Tokens JSON ↓</a><a class="button secondary" href="/registry.json" download>Component registry ↓</a><a class="button secondary" href="/screen-brief.schema.json" download>JSON Schema ↓</a></div>`)+callout('AI에게는 기준을 먼저 전달하세요.','목적 → 패턴 → 컴포넌트 → 토큰 → 상태 → 검수 순서로 실행합니다. 임의 HEX·간격·radius·새 컴포넌트를 만들지 않습니다.')+section('brief','ScreenBrief 만들기',`<form id="briefForm" class="demo-stack"><div class="field"><label for="briefId">화면 ID</label><input class="input" id="briefId" value="docs.typography" required></div><div class="field"><label for="briefPurpose">화면의 목적</label><textarea class="input" id="briefPurpose" rows="2" required>${esc(brief.purpose)}</textarea></div><div class="field"><label for="briefAction">가장 중요한 행동</label><input class="input" id="briefAction" value="명세 복사" required></div><div class="button-row"><button class="button primary" type="submit">JSON 만들기</button><button class="button secondary" type="button" id="briefDownload">양식 다운로드</button></div></form><div style="margin-top:var(--s6)" id="briefOutput">${codePanel(JSON.stringify(brief,null,2),'screen-brief.json')}</div>`)+section('prompt','구현 위임 프롬프트',codePanel('Hudson AI Web Design System v1.0을 구현하세요.\n먼저 저장소 구조와 AGENTS.md, 의존성을 확인하세요.\nScreenBrief의 목적·사용자·주요 행동을 기준으로 기존 Pattern을 선택하세요.\n기존 Component와 semantic token에서 선택하고 임의 값을 추가하지 마세요.\n반응형·키보드·비동기·실패·긴 텍스트를 함께 구현하세요.\n명세의 수용 기준을 검사하고 변경 파일·검증 결과·미해결 항목을 보고하세요.','ai-instruction.txt'))+section('validation','수용 기준',specExcerpt('검수'))+section('full-spec','위임 명세 전체',specExcerpt('AI Kit'));}
function markdown(raw){
 let blocks=[];raw=raw.replace(/```([^\n]*)\n([\s\S]*?)```/g,(_,lang,body)=>{blocks.push(codePanel(body.trim(),lang||'code'));return `\n@@BLOCK${blocks.length-1}@@\n`;});
 const inline=t=>esc(t).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code class="inline">$1</code>').replace(/https:\/\/[^\s<]+/g,u=>`<a class="text-link" href="${u}" target="_blank" rel="noopener">${u}</a>`);
 const lines=raw.split('\n');let out='',list=false;
 for(let i=0;i<lines.length;i++){const l=lines[i];if(!l.trim()){if(list){out+='</ul>';list=false;}continue;}if(l.startsWith('|')&&lines[i+1]?.match(/^\|[- :|]+\|$/)){if(list){out+='</ul>';list=false;}const split=t=>t.trim().slice(1,-1).split('|').map(x=>inline(x.trim()));const h=split(l),rows=[];i+=2;while(lines[i]?.startsWith('|')){rows.push(split(lines[i]));i++;}i--;out+=table(h,rows);continue;}if(l.match(/^@@BLOCK\d+@@$/)){out+=blocks[+l.match(/\d+/)[0]];continue;}if(l.startsWith('### ')){out+=`<h3>${inline(l.slice(4))}</h3>`;continue;}if(l.startsWith('> ')){out+=`<blockquote>${inline(l.slice(2))}</blockquote>`;continue;}if(l.match(/^(- |\d+\. )/)){if(!list){out+='<ul>';list=true;}out+=`<li>${inline(l.replace(/^(- |\d+\. )/,''))}</li>`;continue;}if(list){out+='</ul>';list=false;}out+=`<p>${inline(l)}</p>`;}if(list)out+='</ul>';return out;
}
function specExcerpt(title){let idx=title==='Typography'?6:['Color'].includes(title)?5:['Spacing','Radius','Elevation','Layout'].includes(title)?7:['Motion','Iconography'].includes(title)?10:['Upload','AsyncJob','MediaWorkspace','LiveSession','EmptyState','ErrorRecovery'].includes(title)?9:title==='AI Kit'?13:title==='검수'?15:4;const s=specSections.find(x=>x.title.startsWith(idx+'.'));return s?`<div class="spec-section">${markdown(s.body)}</div>`:'<p>명세를 불러오지 못했어요. <a class="text-link" href="/assets/Hudson_AI_Web_Design_System_Spec.md" download>원본 파일 내려받기</a></p>';}
function specification(){return `<div class="button-row"><a class="button primary" href="/assets/Hudson_AI_Web_Design_System_Spec.md" download>원본 명세 다운로드 ↓</a></div>`+specSections.map((s,i)=>section('spec-'+i,esc(s.title),`<div class="spec-section">${markdown(s.body)}</div>`)).join('');}
function guide(p){if(p.title==='Getting Started')return section('steps','세 단계로 시작하기',rules([['01 · 목적을 정의하세요.','사용자, 가장 중요한 정보, 다음 행동, 필요한 상태를 ScreenBrief에 기록합니다.'],['02 · 기준을 선택하세요.','기존 Pattern·Component·semantic token을 선택해 화면을 조합합니다.'],['03 · 실제로 검수하세요.','키보드, 반응형, 확대, 실패, 긴 텍스트를 확인합니다.'],['04 · 변경을 기록하세요.','새 규칙이 필요하면 이유·영향·예제와 함께 시스템에 반영합니다.']]))+section('technical','실행 구조',codePanel('dist/\n  index.html         문서 Shell\n  app.js             Registry 기반 라우팅·예제\n  style.css          Semantic token 기반 스타일\n  tokens.json        토큰 데이터\n  registry.json      컴포넌트 계약\n  spec.json          원본 명세 전체\n  screen-brief.schema.json\n  assets/            폰트·라이선스·원본 명세','project.structure'))+section('related','다음 단계',related(['/foundations/typography','/components/button','/ai-kit']));
 if(p.title==='Design Principles')return section('laws','UX 원칙을 화면의 기준으로',rules([['Hick · 선택을 구조화','핵심 행동을 먼저 보여주고 고급 옵션은 접습니다. 긴 목록에는 검색을 제공합니다.'],['Fitts · 쉽게 누르게','중요 행동은 충분한 크기와 맥락 가까운 위치를 확보합니다.'],['Jakob · 익숙한 웹 관습','링크는 이동, 버튼은 실행. Cmd/Ctrl+K, Esc 등 익숙한 조작을 따릅니다.'],['Proximity · 관계를 보여주기','라벨·입력·설명·오류는 가깝게, 다른 그룹은 여백으로 구분합니다.'],['Von Restorff · 하나를 강조','작업 맥락당 주요 행동을 하나로 정하고 오렌지를 남용하지 않습니다.'],['AI · 선택하고 조합하기','AI가 값을 새로 발명하기보다 역할과 상태가 정해진 시스템에서 선택하게 합니다.']]))+section('detail','실행 기준',specExcerpt('principles'));
 if(p.title==='Changelog')return section('version','v1.0.0 · 2026. 10. 10.',checklist(['Hudson 브랜드 컬러와 웹 Typography 역할 토큰 정의','반응형 DocsShell, 검색·목차·직접 진입·404 구현','20개 컴포넌트의 상태·API·계약과 인터랙션 예제','8개 Hudson 패턴과 데모 상태 전이','AI Kit, ScreenBrief Schema, 원본 명세 다운로드']))+section('policy','변경과 예외 관리',`<div class="spec-section">${markdown(specSections.find(x=>x.title.startsWith('14.'))?.body??'')}</div>`);
 return section('guidelines','접근성·문장·국제화 기준',specExcerpt('Motion'))+section('checks','검수 기준',specExcerpt('검수'));
}
function body(p){if(p.title==='Typography')return typography();if(p.group==='파운데이션')return foundation(p);if(registry[p.title])return component(p);if(p.group==='작업 패턴')return pattern(p);if(p.title==='Overview')return overview();if(p.title==='AI Kit')return aiKit();if(p.title==='Specification')return specification();return guide(p);}
function footer(p){const i=pages.findIndex(x=>x.path===p.path),prev=pages[i-1],next=pages[i+1];return `<footer class="page-footer">${prev?`<a href="${prev.path}" data-route><small>이전 문서</small>← ${prev.title}</a>`:'<span></span>'}${next?`<a href="${next.path}" data-route><small>다음 문서</small>${next.title} →</a>`:''}</footer><div class="footer-note">Hudson AI Design System · Web v1.0.0<br>규칙은 분명하게, 실행은 유연하게.</div>`;}
let observer;
function render(path,focus=false){path=path.replace(/\/$/,'')||'/foundations/typography';clearTimeout(jobTimer);clearInterval(mediaTimer);currentPage=pages.find(x=>x.path===path);if(!currentPage){main.innerHTML='<header class="page-head"><h1 id="pageTitle" tabindex="-1">문서를 찾을 수 없어요.</h1><p class="page-description">주소를 확인하거나 검색으로 필요한 기준을 찾아보세요.</p></header><a class="button primary" href="/foundations/typography" data-route>Typography로 이동</a>';$('#toc').innerHTML='';return;}
 document.title=currentPage.title+' — Hudson AI Design System';main.innerHTML=header(currentPage)+body(currentPage)+footer(currentPage);$('#sidebar').innerHTML=navHTML();$('#mobileNav').innerHTML=navHTML();const sections=$$('main > .section');const links=sections.map(s=>`<a href="#${s.id}">${esc(s.querySelector('h2').textContent)}</a>`).join('');$('#toc').innerHTML=`<div class="toc-title">On this page</div><nav class="toc-links">${links}</nav><div class="toc-note"><strong>AI와 함께 만들고 있나요?</strong><p>같은 기준을 읽고, 같은 결과를 만드세요.</p><a href="/ai-kit" data-route>AI Kit 살펴보기 ↗</a></div>`;main.querySelector('.page-head').insertAdjacentHTML('afterend',`<details class="mobile-toc"><summary>이 페이지 목차</summary><nav>${links}</nav></details>`);bindPage();if(focus){$('#pageTitle')?.focus({preventScroll:true});window.scrollTo(0,0);}observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('#toc .toc-links a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}},{rootMargin:'-10% 0px -65% 0px'});sections.forEach(s=>observer.observe(s));}
function navigate(path){history.pushState({},'',path);render(path,true);if($('#navDialog').open)$('#navDialog').close();}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();if($('#searchDialog').open)$('#searchDialog').close();navigate(a.getAttribute('href'));}});
window.addEventListener('popstate',()=>{render(location.pathname,true);if(location.hash)$(location.hash)?.scrollIntoView();});
function notify(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('클립보드에 복사했어요.');}catch{const dlg=document.createElement('dialog');dlg.className='demo-dialog';dlg.innerHTML='<h2>직접 복사해 주세요.</h2><p>브라우저에서 클립보드 접근을 허용하지 않았어요.</p><textarea class="input" rows="6" aria-label="복사할 내용"></textarea><button class="button secondary" style="margin-top:var(--s4)">닫기</button>';document.body.append(dlg);dlg.querySelector('textarea').value=text;dlg.querySelector('button').onclick=()=>dlg.close();dlg.addEventListener('close',()=>dlg.remove());dlg.showModal();dlg.querySelector('textarea').select();}}
function download(name,data){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('다운로드를 시작했어요.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-copy'))copy(b.dataset.copy);if(b.hasAttribute('data-copy-source'))copy(b.closest('.code-panel').querySelector('code').textContent);if(b.hasAttribute('data-copy-contract'))copy(JSON.stringify(contract(currentPage),null,2));if(b.hasAttribute('data-download-contract'))download(currentPage.title.toLowerCase()+'.contract.json',contract(currentPage));if(b.hasAttribute('data-demo-action'))notify('예제 행동을 실행했어요. 실제 프로젝트는 생성되지 않습니다.');if(b.hasAttribute('data-open-dialog'))$('#demoDialog').showModal();if(b.hasAttribute('data-close-dialog'))$('#demoDialog').close();if(b.hasAttribute('data-confirm-dialog')){$('#demoDialog').close();notify('데모 변경 사항을 저장했어요.');}if(b.hasAttribute('data-retry'))notify('데모 복구가 완료됐어요. 실제 서버 요청은 없습니다.');if(b.hasAttribute('data-open-search'))openSearch();});
function search(){const q=$('#searchInput').value.toLowerCase().trim();const result=pages.filter(p=>!q||(`${p.title} ${p.group} ${desc[p.title]??registry[p.title]?.purpose??''}`).toLowerCase().includes(q));$('#searchResults').innerHTML=result.length?result.map(p=>`<a class="search-result" href="${p.path}" data-route><strong>${esc(p.title)}</strong><small>${esc(p.group)} · ${p.path}</small></a>`).join(''):'<div class="empty-state"><h3>검색 결과가 없어요.</h3><p>다른 키워드로 검색해 보세요.</p></div>';}
function openSearch(){$('#searchInput').value='';search();$('#searchDialog').showModal();$('#searchInput').focus();}
$('#searchOpen').onclick=openSearch;$('#searchInput').oninput=search;$('#menuOpen').onclick=()=>$('#navDialog').showModal();$('#menuClose').onclick=()=>$('#navDialog').close();
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#searchDialog').open)$('#searchDialog').close();else openSearch();}if($('#searchDialog').open&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const links=$$('#searchResults a');let i=links.indexOf(document.activeElement);i=e.key==='ArrowDown'?Math.min(i+1,links.length-1):Math.max(i-1,0);links[i]?.focus();}});
function on(selector,event,fn){const el=$(selector);if(el)el.addEventListener(event,fn);}
function bindPage(){
 $$('.tab').forEach(t=>{t.onclick=()=>activateTab(t.dataset.tab);t.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.tab');let i=tabs.indexOf(t);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activateTab(tabs[i].dataset.tab);tabs[i].focus();}};});
 function typeUpdate(){const locale=$('#locale')?.value??'ko',scale=+($('#typeScale')?.value??1);const title=locale==='en'?'Give every voice its meaning.':locale==='mixed'?'모든 목소리에, real emotion.':'모든 목소리에 의미를 더하다.';const text=locale==='en'?'Different languages. The same intention. Design an experience with clear hierarchy and a comfortable reading rhythm.':locale==='mixed'?'언어가 달라져도, every feeling comes through. 명확한 위계와 읽기 편한 리듬으로 경험을 설계합니다.':'언어가 달라져도, 전하고 싶은 마음은 그대로. 명확한 위계와 읽기 편한 리듬으로 경험을 설계합니다.';$('#specimenTitle').textContent=title;$('#specimenBody').textContent=text;$('#specimenTitle').style.fontSize=2*scale+'rem';$('#specimenBody').style.fontSize=scale+'rem';$('#typeStage').lang=locale==='en'?'en':'ko';}
 on('#locale','change',typeUpdate);on('#typeScale','change',typeUpdate);on('#narrowToggle','click',e=>{const b=e.currentTarget,v=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(v));$('#typeStage').classList.toggle('narrow',v);});
 on('#loadingDemo','click',e=>{const b=e.currentTarget;if(b.getAttribute('aria-disabled')==='true')return;b.setAttribute('aria-disabled','true');b.setAttribute('aria-busy','true');b.innerHTML='<span class="spinner" aria-hidden="true"></span> 로딩 상태 보기';setTimeout(()=>{if(!b.isConnected)return;b.removeAttribute('aria-disabled');b.removeAttribute('aria-busy');b.textContent='로딩 상태 보기';notify('로딩 상태 시연이 완료됐어요.');},1400);});
 const validate=()=>{const input=$('#projectName'),valid=input.value.trim().length>=2;input.setAttribute('aria-invalid',String(!valid));$('#nameError').hidden=valid;$('#nameError').textContent=valid?'':'프로젝트 이름을 2자 이상 입력해 주세요.';return valid;};on('#projectName','blur',validate);on('#projectName','input',()=>{if($('#projectName').getAttribute('aria-invalid')==='true')validate();});if($('#inputDemo')){$('#inputDemo').noValidate=true;on('#inputDemo','submit',e=>{e.preventDefault();if(validate())notify('프로젝트 이름 검증 완료 · 데모입니다.');else $('#projectName').focus();});on('#inputDemo','reset',()=>{$('#projectName').removeAttribute('aria-invalid');$('#nameError').hidden=true;});}
 on('#languageSelect','change',e=>$('#selectStatus').textContent=e.target.value+'가 선택되었습니다.');
 if($('#languageCombo'))bindCombo();
 on('#switchDemo','click',e=>{const b=e.currentTarget,v=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(v));b.textContent='자동 저장 · '+(v?'켜짐':'꺼짐');$('#switchStatus').textContent='예제 자동 저장이 '+(v?'켜졌어요.':'꺼졌어요.');});on('#toastDemo','click',()=>notify('변경 사항을 저장했어요. · 데모'));on('#drawerDemo','click',()=>$('#navDialog').showModal());on('#motionDemo','click',()=>{$('#motionStatus').textContent='✓ 완료';$('#motionStatus').classList.add('success');notify('상태 전환 시연이 완료됐어요.');});
 if($('#tooltipTrigger')){const show=()=>$('#tooltipText').hidden=false,hide=()=>$('#tooltipText').hidden=true;on('#tooltipTrigger','pointerenter',show);on('#tooltipTrigger','focus',show);on('#tooltipTrigger','pointerleave',hide);on('#tooltipTrigger','blur',hide);on('#tooltipTrigger','keydown',e=>{if(e.key==='Escape')hide();});}
 if($('#demoRows'))bindTable();
 let page=1;function paging(){$('#pageIndicator').textContent=page+' / 3';$('#prevPage').disabled=page===1;$('#nextPage').disabled=page===3;}on('#prevPage','click',()=>{page--;paging();});on('#nextPage','click',()=>{page++;paging();});
 on('#skeletonLoad','click',()=>{$('#skeletonArea').setAttribute('aria-busy','false');$('#skeletonArea').innerHTML='<h3>프로젝트 불러오기 완료</h3><p>데모 콘텐츠가 표시됐어요.</p>';$('#skeletonLoad').disabled=true;});on('#progressRange','input',e=>{$('#demoProgress').value=e.target.value;$('#progressLabel').textContent=e.target.value+'% · 데모 데이터';});
 if($('#fileInput'))bindUpload();if($('#jobStart'))bindJob();if($('#mediaPlay'))bindMedia();if($('#liveDisconnect'))bindLive();
 if($('#briefForm'))bindBrief();
}
function activateTab(id){$$('.tab').forEach(t=>{const v=t.dataset.tab===id;t.setAttribute('aria-selected',String(v));t.tabIndex=v?0:-1;$('#panel-'+t.dataset.tab).hidden=!v;});}
function bindCombo(){const input=$('#languageCombo'),list=$('#languageOptions');const langs=['한국어','English','日本語','Español','Français','Deutsch','中文','Português'];let filtered=[],idx=-1;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');};const choose=v=>{input.value=v;$('#comboStatus').textContent=v+' 선택됨';close();};const show=()=>{filtered=langs.filter(v=>v.toLowerCase().includes(input.value.toLowerCase()));idx=-1;list.hidden=false;input.setAttribute('aria-expanded','true');list.innerHTML=filtered.length?filtered.map((v,i)=>`<div class="nav-link" role="option" id="lang-${i}" aria-selected="false">${esc(v)}</div>`).join(''):'<p class="field-help">검색 결과가 없어요.</p>';list.querySelectorAll('[role=option]').forEach((el,i)=>{el.onpointerdown=e=>{e.preventDefault();choose(filtered[i]);};});};input.oninput=show;input.onfocus=show;input.onblur=close;input.onkeydown=e=>{if(e.key==='Escape'){close();return;}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(list.hidden)show();if(!filtered.length)return;idx=Math.max(0,Math.min(filtered.length-1,idx+(e.key==='ArrowDown'?1:-1)));list.querySelectorAll('[role=option]').forEach((el,i)=>{el.setAttribute('aria-selected',String(i===idx));el.classList.toggle('active',i===idx);});input.setAttribute('aria-activedescendant','lang-'+idx);}if(e.key==='Enter'&&idx>=0&&!list.hidden){e.preventDefault();choose(filtered[idx]);}};
}
function bindTable(){const data=[{name:'Hudson 브랜드 필름',lang:'English',state:'완료'},{name:'글로벌 컨퍼런스',lang:'한국어',state:'검토 필요'},{name:'제품 소개 영상',lang:'日本語',state:'대기'}];let asc=false;const selected=new Set();let visible=[];const update=()=>{const q=$('#tableFilter').value.toLowerCase();visible=data.filter(r=>r.name.toLowerCase().includes(q));if(asc)visible.sort((a,b)=>a.name.localeCompare(b.name,'ko'));$('#demoRows').innerHTML=visible.length?visible.map(r=>`<tr><td><input type="checkbox" aria-label="${esc(r.name)} 선택" data-name="${esc(r.name)}" ${selected.has(r.name)?'checked':''}></td><td>${esc(r.name)}</td><td>${r.lang}</td><td><span class="badge ${r.state==='완료'?'success':r.state==='검토 필요'?'warning':''}">${r.state}</span></td></tr>`).join(''):'<tr><td colspan="4">검색 결과가 없어요. 다른 키워드를 입력하세요.</td></tr>';const all=$('#selectAll');all.checked=visible.length>0&&visible.every(r=>selected.has(r.name));all.indeterminate=visible.some(r=>selected.has(r.name))&&!all.checked;$('#tableStatus').textContent=`데모 데이터 · ${visible.length}개 표시 · ${selected.size}개 선택`;$$('#demoRows input').forEach(i=>i.onchange=()=>{if(i.checked)selected.add(i.dataset.name);else selected.delete(i.dataset.name);update();});};on('#tableFilter','input',update);on('#sortTable','click',()=>{asc=!asc;$('#sortHeader').setAttribute('aria-sort',asc?'ascending':'none');update();});on('#selectAll','change',e=>{visible.forEach(r=>{if(e.target.checked)selected.add(r.name);else selected.delete(r.name);});update();});update();}
function bindUpload(){const output=$('#fileResults'),zone=$('#dropzone');const show=files=>{output.replaceChildren();if(!files.length){output.textContent='선택된 파일이 없어요.';return;}for(const file of files){const el=document.createElement('div');el.textContent=file.name+' · '+(file.size/1024/1024).toFixed(2)+'MB · 전송되지 않음';output.append(el);}};on('#fileInput','change',e=>show(e.target.files));on('#fileLabel','keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#fileInput').click();}});zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');show(e.dataTransfer.files);};}
function bindJob(){let state='queued';const set=(s,label)=>{state=s;$('#jobState').textContent=s;$('#jobStage').textContent=label;$('#jobStart').disabled=['running','canceling'].includes(s);$('#jobCancel').disabled=s!=='running';if(s==='running')$('#jobProgress').removeAttribute('value');else $('#jobProgress').value=s==='succeeded'?100:0;};on('#jobStart','click',()=>{clearTimeout(jobTimer);set('running','번역 중 · 데모');jobTimer=setTimeout(()=>{set('succeeded','데모 작업 완료');notify('상태 전이 시연 완료 · 실제 처리 없음');},3000);});on('#jobCancel','click',()=>{clearTimeout(jobTimer);set('canceling','취소 요청 처리 중');jobTimer=setTimeout(()=>set('canceled','데모 작업 취소됨'),400);});on('#jobFail','click',()=>{clearTimeout(jobTimer);set('failed','데모 처리 실패 · 다시 실행할 수 있어요.');});}
function bindMedia(){let playing=false;const seek=$('#mediaSeek'),play=$('#mediaPlay');const sync=()=>$('#mediaTime').textContent='00:'+String(seek.value).padStart(2,'0');on('#mediaSeek','input',sync);play.onclick=()=>{playing=!playing;play.textContent=playing?'Ⅱ 일시정지':'▶ 재생';play.setAttribute('aria-label',playing?'타임라인 데모 일시정지':'타임라인 데모 재생');clearInterval(mediaTimer);if(playing)mediaTimer=setInterval(()=>{seek.value=+seek.value>=24?0:+seek.value+1;sync();},1000);};}
function bindLive(){on('#liveDisconnect','click',()=>{$('#liveBadge').className='badge danger';$('#liveBadge').textContent='× 연결 끊김';$('#liveReconnect').hidden=false;$('#liveDisconnect').disabled=true;$('#liveStatus').textContent='데모 연결이 끊겼어요. 실제 송출에는 영향이 없습니다.';});on('#liveReconnect','click',()=>{$('#liveBadge').className='badge warning';$('#liveBadge').textContent='↻ 재연결 중';$('#liveReconnect').disabled=true;jobTimer=setTimeout(()=>{$('#liveBadge').className='badge success';$('#liveBadge').textContent='● 연결됨';$('#liveReconnect').hidden=true;$('#liveReconnect').disabled=false;$('#liveDisconnect').disabled=false;$('#liveStatus').textContent='데모 연결 복구 · '+new Intl.DateTimeFormat('ko-KR',{timeStyle:'medium',timeZone:'Asia/Seoul'}).format(new Date())+' KST';},1200);});}
function bindBrief(){const create=()=>({schemaVersion:'1.0.0',systemVersion:'1.0.0',screenId:$('#briefId').value,purpose:$('#briefPurpose').value,audience:['designer','developer','ai'],primaryAction:{label:$('#briefAction').value,actionId:'primary-action'},secondaryActions:[],layout:'DocsShell',density:'comfortable',theme:'light',contentPriority:['purpose','preview','rules'],requiredStates:['ready','error'],dataSource:'static-registry',responsivePolicy:'docs-default',acceptanceCriteria:['keyboard-complete','no-page-overflow','contrast-aa']});on('#briefForm','submit',e=>{e.preventDefault();$('#briefOutput').innerHTML=codePanel(JSON.stringify(create(),null,2),'screen-brief.json');notify('ScreenBrief JSON을 만들었어요.');});on('#briefDownload','click',()=>download('screen-brief.json',create()));}
try{const r=await fetch('/spec.json');if(!r.ok)throw Error('명세 로딩 실패');specSections=await r.json();}catch{notify('명세 본문을 불러오지 못했어요. 원본 다운로드를 이용하세요.');}
render(location.pathname==='/'?'/foundations/typography':location.pathname);if(location.hash){requestAnimationFrame(()=>{const el=document.getElementById(location.hash.slice(1));el?.scrollIntoView();});}
